class Solution {
public:
    int minCost(vector<int>& nums1, vector<int>& nums2) {
        vector<int> diff(80001, 0);
        for (int x : nums1) ++diff[x];
        for (int x : nums2) --diff[x];
        int swaps = 0;
        for (int d : diff) {
            if (abs(d) % 2 != 0) return -1;
            if (d > 0) swaps += d / 2;
        }
        return swaps;
    }
};
